"""Edge, part A: delivery and protection – DNS servers, global balancing (GSLB), CDN, HTTP cache, WAF, DDoS protection, proxies and the
network services (time, DHCP, IPAM).

Software and appliances are `svc` / `lbsvc` / `appliance` (instances to size, `cap` where they sit on the request path); a service that exists
only as a provider's cloud is `saas` (trait `managed`: the provider's SLA, not instances, is what the engine reads). Tools of the control plane
(time, DHCP, IPAM) carry `platform` and no `cap`: nothing in the model sends requests to them.
"""
from forge import *

FUNCTIONS = {"edge": [
    ("ddos", "Защита от DDoS", "DDoS protection", "shield-alert"),
    ("network-services", "Сетевые службы (NTP, DHCP, IPAM)", "Network services (NTP, DHCP, IPAM)", "ethernet-port"),
]}
IAC = {"ddos": "appliance", "network-services": "network"}

# what a DNS-based balancer does when a site is lost: a health check, the failures it tolerates and the TTL of the answer (HA-GSLB-01, the simulator)
GSLB_PROBES = [
    num("healthCheckSeconds", "Интервал health-check", "Health-check interval", unit_="s", min=1, default=10, group="failover"),
    num("failThreshold", "Порог отказов", "Failure threshold", min=1, default=3, group="failover"),
    num("dnsTtlSeconds", "DNS TTL", "DNS TTL", unit_="s", min=0, default=30, group="failover"),
]
# (a plain string: arch.k() turns a (ru, en) tuple into {"ru": "ru", "en": "en"} when it hands it on to kind())
GSLB_SUB = "health-check {healthCheckSeconds}s"
# a WAF filters or only watches
WAF_MODE = enum("mode", "Режим", "Mode", [("block", "Блокировка", "Blocking"), ("detect", "Только обнаружение", "Detection only")], default="block", group="security")
WAF_SUB = "{replicas}× · {mode}"

